class Solution {
    public int findLHS(int[] nums){
        Map<Integer,Integer> counts=new HashMap<>();
        for(int value:nums)counts.put(value,counts.getOrDefault(value,0)+1);
        int best=0;
        for(Map.Entry<Integer,Integer> entry:counts.entrySet())if(counts.containsKey(entry.getKey()+1))best=Math.max(best,entry.getValue()+counts.get(entry.getKey()+1));
        return best;
    }
}

code.kotlin:
class Solution {
    fun findLHS(nums:IntArray):Int{
        val counts=hashMapOf<Int,Int>();
        for(value in nums)counts[value]=(counts[value]?:0)+1;
        var best=0;
        for((value,count) in counts){
            val next=counts[value+1];
            if(next!=null)best=maxOf(best,count+next)
        };
        return best
    }
}

code.cpp:
class Solution {
    public: int findLHS(vector<int>& nums){
        unordered_map<int,int> counts;
        for(int value:nums)++counts[value];
        int best=0;
        for(auto [value,count]:counts)if(counts.count(value+1))best=max(best,count+counts[value+1]);
        return best;
    }
};
